from dataclasses import dataclass

from aerona.rules.groups import RuleGroup
from aerona.rules.model import Spanned, rule, span

G = RuleGroup.DISEASE


@dataclass(frozen=True)
class EpidemiologyRules(Spanned):
    neutral_lethality: int = rule(30, 1, 100, G, "Lethality at which a disease kills as many as the old plague did")
    neutral_virulence: int = rule(40, 1, 100, G, "Virulence at which a disease spreads as readily as the old plague did")
    reuse_disease_chance: int = rule(70, 0, 100, G, "A new plague is an old disease of the region or its neighbours rather than a new one (%)")
    immunity_strength_pct: int = rule(85, 0, 100, G, "Protection an immune share gives against its disease (%)")
    survivor_immunity_pct: int = rule(60, 0, 100, G, "Share of the struck who are immune after an outbreak (%)")
    child_immunity_loss_pct: int = rule(50, 0, 100, G, "Share of children's immunity lost each epoch as the immune grow up and the newborn arrive (%)")
    herd_floor_pct: int = rule(30, 0, 100, G, "Lowest herd-immunity threshold of the mildest disease (%)")
    outbreak_years: int = span(2, 1, 1250, G, "Years an outbreak lingers before it wanes")
    waning_death_pct: int = rule(30, 0, 100, G, "Deaths of a lingering outbreak compared with its first epoch (%)")
    infected_pct: int = rule(25, 0, 100, G, "Share of a struck community infected at the outbreak's start, at neutral virulence (%)")
    crowd_population: int = rule(30000, 1, 100000000, G, "Community size at which a disease spreads as in the most crowded land")
    crowd_spread_pct: int = rule(60, 0, 300, G, "Extra spread at the most crowded land (%)")
    load_spread_pct: int = rule(50, 0, 300, G, "Extra spread at the heaviest disease load of the land (%)")
    sanitation_spread_pct: int = rule(50, 0, 100, G, "Spread removed by full sanitation (%)")
    climate_match_pct: int = rule(140, 0, 500, G, "Spread where the climate suits the disease (%)")
    climate_mismatch_pct: int = rule(60, 0, 500, G, "Spread where the climate is wrong for the disease (%)")
    route_spread_chance: int = rule(25, 0, 100, G, "A busy trade route carries an outbreak to its far end in an epoch (%)")
    army_spread_chance: int = rule(35, 0, 100, G, "An army leaving a sick land carries the disease home or to the foe (%)")
    journey_spread_chance: int = rule(20, 0, 100, G, "Travellers leaving a sick land carry the disease to where they arrive (%)")
    quarantine_spread_pct: int = rule(30, 0, 100, G, "Spread kept out of or into a quarantined land (%)")
    endemic_chance: int = rule(25, 0, 100, G, "An outbreak that wanes in a wet, warm or crowded land stays endemic (%)")
    endemic_load: int = rule(20, 0, 100, G, "Disease load an endemic disease adds to its land")
    endemic_decay: int = rule(2, 0, 100, G, "Endemic load lost each epoch where no outbreak renews it")
    virgin_soil_pct: int = rule(250, 100, 1000, G, "Lethality against a people that has never met the disease (%)")
    mutation_immune_pct: int = rule(150, 0, 500, G, "Weight of an immune population in pushing a disease to a new strain (%)")
    mutation_cap: int = rule(2, 0, 50, G, "Most new strains in an epoch")
    stigma_purity: int = rule(40, -100, 100, G, "Purity value at which a people expels its sick")
    expel_pct: int = rule(5, 0, 100, G, "Share of the infected a purity-minded community drives out (%)")
    colony_min: int = rule(150, 1, 1000000, G, "Expelled sick needed to found a colony of the sick")
    hospital_mercy: int = rule(30, -100, 100, G, "Mercy value at which a community with medicine builds a hospital")
    hospital_lethality_pct: int = rule(70, 0, 100, G, "Lethality kept in a land with a hospital (%)")
    hospital_healer_pct: int = rule(150, 100, 500, G, "Healing practice gained in a community with a hospital (%)")
    cure_lethality_pct: int = rule(25, 0, 100, G, "Lethality kept where the cure is known (%)")
    quarantine_years: int = span(1, 1, 1250, G, "Years a quarantine holds")
    quarantine_unrest: int = rule(6, 0, 100, G, "Unrest a quarantine causes")
    essence_per_outbreak: int = rule(3, 0, 1000, G, "Essence a plague-domain son gains per outbreak in its world")
    creator_essence_per_outbreak: int = rule(6, 0, 1000, G, "Essence the son who loosed a disease gains per outbreak of it")
    siege_attrition_pct: int = rule(4, 0, 100, G, "Soldiers a besieging army loses to camp disease in an epoch at the heaviest disease load (%)")
    foreign_army_attrition_pct: int = rule(6, 0, 100, G, "Soldiers an army loses in an epoch in a land whose endemic disease its people has never met (%)")
    minor_illness_pct: int = rule(4, 0, 100, G, "Work lost to colds and fevers in the cold and wet season at the heaviest disease load (%)")
    tradition_dead_min: int = rule(2000, 1, 100000000, G, "Dead of one outbreak that leave a plague tradition")
    medicine_pressure_pct: int = rule(150, 100, 1000, G, "Medicine deepening where a disease is endemic (%)")
    neutral_chronic_rate: int = rule(15, 1, 100, G, "Chronic rate at which a named survivor keeps a lasting illness as often as after the old plague")
    incubation_hidden_pct: int = rule(12, 0, 100, G, "Share of a new outbreak's first epoch that passes unseen per sampled year of incubation (%)")
    incubation_spread_pct: int = rule(80, 0, 500, G, "Extra spread of an unseen outbreak, carried off by travellers before anyone knows (%)")
    incubation_delay_pct: int = rule(60, 0, 100, G, "Share of an unseen outbreak's first deaths that fall in the next epoch instead (%)")
    air_crowd_pct: int = rule(150, 0, 500, G, "Weight of crowding for a disease borne on the air (%)")
    air_cold_pct: int = rule(130, 0, 500, G, "Spread of an airborne disease in a cold or dry land where people huddle indoors (%)")
    water_sanitation_pct: int = rule(180, 0, 500, G, "Weight of sanitation against a waterborne disease (%)")
    water_river_pct: int = rule(160, 0, 500, G, "Spread of a waterborne disease along great rivers and through wetlands (%)")
    water_dry_pct: int = rule(60, 0, 500, G, "Spread of a waterborne disease in a land without rivers or marsh (%)")
    touch_contact_pct: int = rule(160, 0, 500, G, "Spread of a touch-borne disease carried by traders, armies and travellers (%)")
    touch_still_pct: int = rule(70, 0, 500, G, "Spread of a touch-borne disease to neighbours without trade or march (%)")
    bite_host_pct: int = rule(200, 0, 1000, G, "Spread of a bite-borne disease where its host is most abundant (%)")
    bite_hostless_pct: int = rule(10, 0, 100, G, "Spread of a bite-borne disease where none of its hosts live (%)")
    host_spread_pct: int = rule(80, 0, 500, G, "Extra spread of a disease where its host species is most abundant (%)")
    spirit_magic_pct: int = rule(160, 0, 500, G, "Spread of a spirit-borne disease in the densest magic (%)")
    spirit_ley_pct: int = rule(140, 0, 500, G, "Spread of a spirit-borne disease in a land on a ley line (%)")
    spirit_faith_pct: int = rule(50, 0, 100, G, "Spread of a spirit-borne disease kept out by the most pious community (%)")
    void_scar_pct: int = rule(250, 0, 1000, G, "Spread of a void-borne disease where the void has scarred the land deepest (%)")
    void_clean_pct: int = rule(20, 0, 100, G, "Spread of a void-borne disease in a land the void never touched (%)")
    curse_bound_pct: int = rule(150, 0, 500, G, "Spread of a curse while the god who laid it lives (%)")
    curse_unbound_pct: int = rule(40, 0, 100, G, "Spread of a curse whose god is gone or never was (%)")
    route_busy_volume: int = rule(1500, 1, 1000000, G, "Goods carried in an epoch at which a trade route carries disease at its full chance")
    route_volume_floor_pct: int = rule(20, 0, 100, G, "Chance a near-empty trade route still carries disease, against a busy one (%)")
    route_volume_cap_pct: int = rule(300, 100, 1000, G, "Most a very busy trade route can raise its chance of carrying disease (%)")
    army_spread_size: int = rule(2000, 1, 1000000, G, "Soldiers at which an army carries disease at its full chance")
    army_size_cap_pct: int = rule(300, 100, 1000, G, "Most a great host can raise its chance of carrying disease (%)")
    endemic_settler_pct: int = rule(80, 0, 100, G, "Pull of a land for settlers lost at the heaviest endemic disease load (%)")
    host_emergence_pct: int = rule(60, 0, 100, G, "Chance a new disease of a land rich in plague-bearing beasts takes the most abundant as its host (%)")
    host_endemic_pct: int = rule(50, 0, 100, G, "Endemic load a host species keeps alive at its greatest abundance, against the full endemic load (%)")
    host_gone_decay_pct: int = rule(400, 100, 2000, G, "Endemic decay where none of the disease's hosts live any more, against normal decay (%)")
    sick_share_pct: int = rule(60, 0, 100, G, "Share of the infected who lie sick in their community's cohorts at once (%)")
    sick_cap_pct: int = rule(50, 0, 100, G, "Most of a community that can lie sick at once (%)")
    sick_death_weight_pct: int = rule(400, 100, 2000, G, "Weight of the sick in a plague's deaths against the healthy (%)")
    sick_work_pct: int = rule(30, 0, 100, G, "Work left to the sick in a job their disease's target function serves (%)")
    sick_spared_work_pct: int = rule(70, 0, 100, G, "Work left to the sick in jobs their disease spares (%)")
    sick_levy_pct: int = rule(40, 0, 100, G, "Share of sick adults who can still be levied when their disease spares breath, body and sight (%)")
    chronic_function_loss_pct: int = rule(15, 0, 100, G, "Body function lost to a disease's lasting illness per point of its severity (%)")
    backfill_immunity_pct: int = rule(40, 0, 100, G, "Immunity a past plague leaves in the communities it struck, before fading (%)")

    @property
    def outbreak_epochs(self) -> int:
        return self.epochs(self.outbreak_years)

    @property
    def quarantine_epochs(self) -> int:
        return self.epochs(self.quarantine_years)
